// Runs server.mjs on dataFile until it exits; one that starts instead is killed after 5 s.
function runServer(dataFile) {
  const server = fileURLToPath(new URL('../server.mjs', import.meta.url))
  const env = { ...process.env, PORT: '0', DATA_FILE: dataFile }
  return spawnSync(process.execPath, [server], { env, encoding: 'utf8', timeout: 5000 })
}

test('the server will not start on a DATA_FILE in a missing folder, or on a folder', t => {
  const data = tempDataFile()
  t.after(data.cleanup)
  const folder = dirname(data.file)
  const missing = join(folder, 'missing', 'groups.json')
  for (const [file, line] of [
    [missing, `cannot start: folder for DATA_FILE ${missing} does not exist`],
    [folder, `cannot start: DATA_FILE ${folder} is a folder, not a file`],
  ]) {
    const r = runServer(file)
    assert.equal(r.status, 1, file)
    assert.equal(r.stdout, '')
    assert.equal(r.stderr, `${line}\n`)
  }
})
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { balances, expenseView, paymentView, settleUp, splitEvenly } from '../lib/ledger.mjs'

const group = { id: 'trip', name: 'Trip', members: ['Ann', 'Ben', 'Cara'] }

test('splitEvenly gives everyone the same part, in the order given', () => {
  assert.deepEqual(splitEvenly(900, ['Cara', 'Ann', 'Ben']), [['Cara', 300], ['Ann', 300], ['Ben', 300]])
  assert.deepEqual(splitEvenly(1250, ['Ann']), [['Ann', 1250]])
})

test('expenseView shows amounts as numbers with each share', () => {
  const expense = { id: 4, group: 'trip', description: 'Fuel', payer: 'Ben', amount: 1250, split: ['Ann', 'Ben'] }
  assert.deepEqual(expenseView(expense), {
    id: 4, description: 'Fuel', payer: 'Ben', amount: 12.5, split: ['Ann', 'Ben'], shares: { Ann: 6.25, Ben: 6.25 },
  })
})

test('paymentView shows the amount as a number', () => {
  assert.deepEqual(paymentView({ id: 2, group: 'trip', from: 'Ben', to: 'Ann', amount: 725 }), { id: 2, from: 'Ben', to: 'Ann', amount: 7.25 })
})

test('balances starts every member at 0', () => {
  const state = { groups: [group], expenses: [], payments: [] }
  assert.deepEqual(balances(state, group), { Ann: 0, Ben: 0, Cara: 0 })
})

test('balances: the payer is owed the others\' shares, and payments move money back', () => {
  const state = {
    groups: [group],
    expenses: [
      { id: 1, group: 'trip', description: 'Hotel', payer: 'Ann', amount: 9000, split: ['Ann', 'Ben', 'Cara'] },
      { id: 2, group: 'trip', description: 'Taxi', payer: 'Ben', amount: 2000, split: ['Ben', 'Cara'] },
      { id: 3, group: 'other', description: 'Elsewhere', payer: 'Ann', amount: 5000, split: ['Ann', 'Ben'] },
    ],
    payments: [{ id: 1, group: 'trip', from: 'Cara', to: 'Ann', amount: 3000 }],
  }
  assert.deepEqual(balances(state, group), { Ann: 30, Ben: -20, Cara: -10 })
})

test('settleUp is empty when everyone is square', () => {
  const state = { groups: [group], expenses: [], payments: [] }
  assert.deepEqual(settleUp(state, group), [])
})

test('settleUp: whoever owes the most pays whoever is owed the most, until all are square', () => {
  const four = { ...group, members: ['Ann', 'Ben', 'Cara', 'Dev'] }
  const pay = (id, from, to, amount) => ({ id, group: 'trip', from, to, amount })
  // Balances: Ann 50, Ben 30, Cara -60, Dev -20.
  const state = { groups: [four], expenses: [], payments: [pay(1, 'Ann', 'Cara', 5000), pay(2, 'Ben', 'Dev', 2000), pay(3, 'Ben', 'Cara', 1000)] }
  assert.deepEqual(settleUp(state, four), [
    { from: 'Cara', to: 'Ann', amount: 50 },
    { from: 'Dev', to: 'Ben', amount: 20 },
    { from: 'Cara', to: 'Ben', amount: 10 },
  ])
})
import { test } from 'node:test'
import assert from 'node:assert/strict'
import {
  parseAmount, parseDescription, parseGroupId, parseGroupName, parseMember, parseMembers, parseSplit, ValidationError,
} from '../lib/validate.mjs'

const members = ['Ann', 'Ben', 'Cara']

test('parseGroupId accepts lower-case letters, digits and dashes, starting with a letter', () => {
  assert.equal(parseGroupId('trip-2025'), 'trip-2025')
  assert.equal(parseGroupId('a'.repeat(30)), 'a'.repeat(30))
  for (const v of ['', 'Trip', '2trip', '-trip', 'trip 1', 'a'.repeat(31), 7, undefined]) {
    assert.throws(() => parseGroupId(v), ValidationError, `id ${JSON.stringify(v)}`)
  }
})

test('parseGroupName and parseDescription want non-empty text within their limits', () => {
  assert.equal(parseGroupName('Ski trip'), 'Ski trip')
  assert.equal(parseDescription('Dinner, day 1'), 'Dinner, day 1')
  for (const v of ['', '   ', 'x'.repeat(101), 3, null]) assert.throws(() => parseGroupName(v), ValidationError)
  for (const v of ['', ' ', 'x'.repeat(201), [], undefined]) assert.throws(() => parseDescription(v), ValidationError)
  assert.equal(parseDescription('x'.repeat(200)).length, 200)
})

test('parseMembers accepts 2 to 20 different valid names', () => {
  assert.deepEqual(parseMembers(['Ann', 'ann']), ['Ann', 'ann'])
  assert.equal(parseMembers(Array.from({ length: 20 }, (_, i) => `P${i}`)).length, 20)
})

test('parseMembers rejects short, long, repeated or badly named lists', () => {
  const tooMany = Array.from({ length: 21 }, (_, i) => `P${i}`)
  for (const v of [['Ann'], tooMany, ['Ann', 'Ann'], ['Ann', '1st'], ['Ann', 'B c'], ['Ann', 5], 'Ann,Ben']) {
    assert.throws(() => parseMembers(v), ValidationError, JSON.stringify(v))
  }
})

test('parseAmount turns an amount into whole cents', () => {
  assert.equal(parseAmount(12.5), 1250)
  assert.equal(parseAmount(30), 3000)
  assert.equal(parseAmount(0.25), 25)
  assert.equal(parseAmount(0.01), 1)
  assert.equal(parseAmount(1000000), 100000000)
})

test('parseAmount rejects zero, negatives, extra decimals, strings and too much', () => {
  for (const v of [0, -5, 1.234, '12', 1000000.01, NaN, Infinity, 1e21, null, undefined]) {
    assert.throws(() => parseAmount(v), ValidationError, `amount ${String(v)}`)
  }
})

test('parseMember accepts only names of the group, and says which field is wrong', () => {
  assert.equal(parseMember('Ben', members, 'payer is wrong'), 'Ben')
  assert.throws(() => parseMember('Dan', members, 'payer is wrong'), { message: 'payer is wrong' })
  assert.throws(() => parseMember('ben', members, 'payer is wrong'), ValidationError)
})

test('parseSplit defaults to every member and checks a given list', () => {
  assert.deepEqual(parseSplit(undefined, members), members)
  assert.deepEqual(parseSplit(['Cara', 'Ann'], members), ['Cara', 'Ann'])
  for (const v of [[], ['Ann', 'Ann'], ['Dan'], 'Ann', null]) {
    assert.throws(() => parseSplit(v, members), ValidationError, JSON.stringify(v))
  }
})
